import copy
import json
from pathlib import Path

ROOT = Path('outputs/dracula-food')
LANGS = ('ro', 'en', 'de')
DATE = '2026-09-25'

def T(ro, en, de):
    return dict(zip(LANGS, (ro, en, de)))

sources = []
def source(id, title, url, scope, **extra):
    sources.append(dict(id=id, title=title, url=url, accessed_at=DATE, scope=scope, **extra))

for fid in (170187, 170581, 168165, 168164, 171724):
    d = json.loads(Path(f'work/usda-{fid}.json').read_text(encoding='utf-8-sig'))
    source(f'usda-{fid}', f'USDA FoodData Central: {d["description"]}', f'https://fdc.nal.usda.gov/food-details/{fid}/nutrients', 'Generic ingredient composition, not a Dracula Food batch or product analysis.', fdc_id=fid, data_type=d['dataType'], verified_via_api=True, api_endpoint=f'https://api.nal.usda.gov/fdc/v1/food/{fid}')

